import React, { useState, useEffect, useContext } from "react";
import jsPDF from "jspdf";
import "jspdf-autotable";
import axios from "axios";
import { Link, useNavigate } from "react-router-dom";
import SearchBar from "./SearchBar";
import { OrderContext } from "./OrderContext";

const AllOrders = () => {
    const [orders, setOrders] = useState([]);
    const [searchQuery, setSearchQuery] = useState("");
    const [loading, setLoading] = useState(true);
    const navigate = useNavigate();
    const { ordersChanged } = useContext(OrderContext);

    useEffect(() => {
        const fetchOrders = async () => {
            try {
                setLoading(true);
                const res = await axios.get("http://localhost:5000/orders/");
                setOrders(Array.isArray(res.data.orders) ? res.data.orders : []);
            } catch (err) {
                console.error("Error fetching orders:", err);
            } finally {
                setLoading(false);
            }
        };
        fetchOrders();
    }, [ordersChanged]);

    const generateReport = () => {
        const doc = new jsPDF();
        doc.text("Order Management Report", 14, 16);
        
        const columns = [
            "First Name", "Last Name", "Email", "Phone", "Address", "City", "Order ID", "Pickup Time", "Status"
        ];
        const rows = orders.map((order) => [
            order.firstName, order.lastName, order.email,
            order.phoneNumber, order.address, order.city,
            order.orderId, order.pickupTime, order.orderStatus
        ]);
        
        doc.autoTable({ head: [columns], body: rows, startY: 22 });
        doc.save("Orders_Report.pdf");
    };

    return (
        <div style={{ padding: "20px", backgroundColor: "#f3f4f6", minHeight: "100vh" }}>
            <h1 style={{ textAlign: "center", fontSize: "2.25rem", fontWeight: "bold", marginBottom: "1.5rem" }}>
                All Orders
            </h1>
            
            <div style={{ display: "flex", justifyContent: "center", marginBottom: "20px" }}>
                <SearchBar onSearch={setSearchQuery} />
            </div>

            {loading ? (
                <div style={{ textAlign: "center", padding: "20px" }}>Loading orders...</div>
            ) : (
                <table style={{ width: "100%", borderCollapse: "collapse", backgroundColor: "#fff", textAlign: "left" }}>
                    <thead style={{ backgroundColor: "#4a5568", color: "white" }}>
                        <tr>
                            <th style={{ padding: "10px", borderBottom: "2px solid #e2e8f0" }}>First Name</th>
                            <th style={{ padding: "10px", borderBottom: "2px solid #e2e8f0" }}>Last Name</th>
                            <th style={{ padding: "10px", borderBottom: "2px solid #e2e8f0" }}>Email</th>
                            <th style={{ padding: "10px", borderBottom: "2px solid #e2e8f0" }}>Phone</th>
                            <th style={{ padding: "10px", borderBottom: "2px solid #e2e8f0" }}>Address</th>
                            <th style={{ padding: "10px", borderBottom: "2px solid #e2e8f0" }}>City</th>
                            <th style={{ padding: "10px", borderBottom: "2px solid #e2e8f0" }}>Order ID</th>
                            <th style={{ padding: "10px", borderBottom: "2px solid #e2e8f0" }}>Pickup Time</th>
                            <th style={{ padding: "10px", borderBottom: "2px solid #e2e8f0" }}>Status</th>
                        </tr>
                    </thead>
                    <tbody>
                        {orders.length > 0 ? (
                            orders.map((order) => (
                                <tr key={order._id}>
                                    <td style={{ padding: "10px", borderBottom: "1px solid #e2e8f0" }}>{order.firstName}</td>
                                    <td style={{ padding: "10px", borderBottom: "1px solid #e2e8f0" }}>{order.lastName}</td>
                                    <td style={{ padding: "10px", borderBottom: "1px solid #e2e8f0" }}>{order.email}</td>
                                    <td style={{ padding: "10px", borderBottom: "1px solid #e2e8f0" }}>{order.phoneNumber}</td>
                                    <td style={{ padding: "10px", borderBottom: "1px solid #e2e8f0" }}>{order.address}</td>
                                    <td style={{ padding: "10px", borderBottom: "1px solid #e2e8f0" }}>{order.city}</td>
                                    <td style={{ padding: "10px", borderBottom: "1px solid #e2e8f0" }}>{order.orderId}</td>
                                    <td style={{ padding: "10px", borderBottom: "1px solid #e2e8f0" }}>{order.pickupTime}</td>
                                    <td style={{ padding: "10px", borderBottom: "1px solid #e2e8f0" }}>{order.orderStatus}</td>
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan="9" style={{ textAlign: "center", padding: "10px" }}>No orders available</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            )}
            
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginTop: "20px" }}>
                <button
                    onClick={generateReport}
                    style={{
                        padding: "12px 20px",
                        backgroundColor: "black",
                        color: "white",
                        border: "none",
                        borderRadius: "5px",
                        cursor: "pointer",
                        fontSize: "16px",
                        width: "100%",
                        maxWidth: "200px",
                        marginBottom: "15px"
                    }}
                >
                    Generate Report
                </button>
                <button
                    onClick={() => navigate("/")}
                    style={{
                        padding: "12px 20px",
                        backgroundColor: "#dc2626",
                        color: "white",
                        border: "none",
                        borderRadius: "5px",
                        cursor: "pointer",
                        fontSize: "16px",
                        width: "100%",
                        maxWidth: "200px",
                    }}
                >
                    Back to Home
                </button>
            </div>
        </div>
    );
};

export default AllOrders;
